public int[] topoSortDFS(int n, int[][] edges) {
    List<Integer>[] adj = new List[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    for (int[] e : edges) adj[e[0]].add(e[1]);

    int[] state = new int[n];          // 0=white, 1=gray, 2=black
    Deque<Integer> post = new ArrayDeque<>();
    boolean[] hasCycle = {false};
    for (int i = 0; i < n; i++) {
        if (state[i] == 0) dfs(i, adj, state, post, hasCycle);
    }
    if (hasCycle[0]) return new int[]{};
    int[] order = new int[n];
    int idx = 0;
    while (!post.isEmpty()) order[idx++] = post.pop();   // reverse postorder
    return order;
}

private void dfs(int u, List<Integer>[] adj, int[] state,
                 Deque<Integer> post, boolean[] hasCycle) {
    state[u] = 1;
    for (int v : adj[u]) {
        if (state[v] == 1) { hasCycle[0] = true; return; }
        if (state[v] == 0) dfs(v, adj, state, post, hasCycle);
    }
    state[u] = 2;
    post.push(u);
}

