import sys

def topo_sort_dfs(self, n: int, edges: list[list[int]]) -> list[int]:
    sys.setrecursionlimit(300000)      # deep chains can exceed default
    adj: list[list[int]] = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    state = [0] * n                    # 0=white, 1=gray, 2=black
    post: list[int] = []
    has_cycle = False

    def dfs(u):
        nonlocal has_cycle
        state[u] = 1
        for v in adj[u]:
            if state[v] == 1:
                has_cycle = True
                return
            if state[v] == 0:
                dfs(v)
        state[u] = 2
        post.append(u)

    for i in range(n):
        if state[i] == 0:
            dfs(i)
    return [] if has_cycle else post[::-1]

