public int[] topoSortKahn(int n, int[][] edges) {
    List<Integer>[] adj = new List[n];
    for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
    int[] indegree = new int[n];
    for (int[] e : edges) {
        adj[e[0]].add(e[1]);
        indegree[e[1]]++;
    }

    Deque<Integer> queue = new ArrayDeque<>();
    for (int v = 0; v < n; v++) {
        if (indegree[v] == 0) queue.offer(v);
    }

    int[] order = new int[n];
    int idx = 0;
    while (!queue.isEmpty()) {
        int u = queue.poll();
        order[idx++] = u;
        for (int v : adj[u]) {
            if (--indegree[v] == 0) queue.offer(v);
        }
    }

    return idx == n ? order : new int[]{};   // incomplete ⇒ cycle
}

